groundId":"opposites","approved":true},{"id":"opposites-07","version":0,"categoryId":"opposites","prompt":"Happy","target":"Sad","acceptedAnswers":[],"hints":["An unhappy emotional state.","The answer starts with “S”.","The answer has 1 word and 3 non-space characters."],"backgroundId":"opposites","approved":true},{"id":"opposites-08","version":0,"categoryId":"opposites","prompt":"Full","target":"Empty","acceptedAnswers":[],"hints":["Containing nothing.","The answer starts with “E”.","The answer has 1 word and 5 non-space characters."],"backgroundId":"opposites","approved":true},{"id":"opposites-09","version":0,"categoryId":"opposites","prompt":"Near","target":"Far","acceptedAnswers":[],"hints":["At a great distance.","The answer starts with “F”.","The answer has 1 word and 3 non-space characters."],"backgroundId":"opposites","approved":true},{"id":"opposites-10","version":0,"categoryId":"opposites","prompt":"Early","target":"Late","acceptedAnswers":[],"hints":["After the expected time.","The answer starts with “L”.","The answer has 1 word and 4 non-space characters."],"backgroundId":"opposites","approved":true}]}$catalog$; c jsonb; p jsonb; answer text; begin
