create function wordpairs.freeze_category() returns trigger language plpgsql as $$
begin
  if exists(select 1 from wordpairs.word_pairs where category_id=old.id and approved) then raise exception 'Playable category versions are immutable' using errcode='23514'; end if;
  return case when tg_op='DELETE' then old else new end;
end $$;
create trigger freeze_category before update or delete on wordpairs.categories for each row execute function wordpairs.freeze_category();

create function public.wordpairs_catalog() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,wordpairs as $$
declare categories jsonb; pairs jsonb; begin
  if (select count(*) from wordpairs.word_pairs where approved)>4096 then return jsonb_build_object('ok',false,'error',jsonb_build_object('code','SERVICE_LIMIT')); end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'version',version,'name',name,'backgroundId',background_id,'approved',approved) order by id collate "C"),'[]') into categories from wordpairs.categories where approved;
  select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'version',p.version,'categoryId',p.category_id,'prompt',p.prompt,'target',p.target,'acceptedAnswers',coalesce((select jsonb_agg(answer order by answer collate "C") from wordpairs.accepted_answers a where a.pair_id=p.id and a.pair_version=p.version),'[]'::jsonb),'hints',p.hints,'backgroundId',c.background_id,'approved',p.approved) order by p.id collate "C",p.version),'[]') into pairs from wordpairs.word_pairs p join wordpairs.categories c on c.id=p.category_id where p.approved and c.approved;
  return jsonb_build_object('ok',true,'value',jsonb_build_object('categories',categories,'pairs',pairs));
end $$;

create function public.wordpairs_match_get(p_id text) returns jsonb language sql stable security definer set search_path=pg_catalog,wordpairs as $$
  select state from wordpairs.aggregates where kind='match' and id=p_id
$$;
create function public.wordpairs_match_starts(p_limit integer) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,wordpairs as $$
begin
  if p_limit is null or p_limit not between 1 and 25 then raise exception 'Invalid limit' using errcode='22023'; end if;
  return (select coalesce(jsonb_agg(id),'[]') from (select r.id from wordpairs.aggregates r where r.kind='room' and r.state->>'status'='playing' and not exists(select 1 from wordpairs.aggregates m where m.kind='match' and m.id=r.id) order by r.id collate "C" limit p_limit) pending);
end $$;
create function public.wordpairs_match_create(p_match jsonb,p_event jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,wordpairs as $$
declare room_state jsonb; prior jsonb; match_id text:=p_match->>'id'; begin
  select state into room_state from wordpairs.aggregates where kind='room' and id=match_id for update;
  if room_state is null then return jsonb_build_object('ok',false,'error',jsonb_build_object('code','NOT_FOUND')); end if;
  select state into prior from wordpairs.aggregates where kind='match' and id=match_id;
  if prior is not null then return jsonb_build_object('ok',true,'value',prior); end if;
  if room_state->>'status'<>'playing' or p_match->>'roomId' is distinct from match_id or p_match->'roster' is distinct from room_state->'startedRoster' or
    jsonb_array_length(p_match->'roster') not between 2 and 25 or (p_match->>'version')::integer<>0 or p_match->>'status'<>'choosing' or p_match->>'startedAt' is distinct from room_state->>'startedAt' or not (p_match->'roster' ? (p_match->>'anchorId')) or p_match->>'chooserId' is distinct from p_match->>'anchorId' then return jsonb_build_object('ok',false,'error',jsonb_build_object('code','VALIDATION_ERROR')); end if;
  if p_event->>'aggregateType' is distinct from 'match' or p_event->>'aggregateId' is distinct from match_id or (p_event->>'version')::integer is distinct from 0 then raise exception 'Invalid event' using errcode='23514'; end if;
  insert into wordpairs.aggregates(kind,id,version,state) values('match',match_id,0,p_match);
  insert into wordpairs.outbox_events(id,aggregate_kind,aggregate_id,aggregate_version,schema_version,event_type,audience,payload) values(p_event->>'id','match',match_id,0,1,'MatchCreated',p_event->'audience',p_event->'payload');
  return jsonb_build_object('ok',true,'value',p_match);
end $$;

create function wordpairs.sync_match_projection() returns trigger language plpgsql set search_path=pg_catalog,wordpairs as $$
declare r jsonb; a jsonb; s jsonb; begin
  if new.kind<>'match' or not (new.state ? 'roster') then return new; end if;
  if tg_op='INSERT' then
    insert into wordpairs.matches(id,room_id,anchor_id,status,started_at) values(new.id,new.state->>'roomId',new.state->>'anchorId',new.state->>'status',to_timestamp((new.state->>'startedAt')::double precision/1000));
    insert into wordpairs.match_players(match_id,profile_id,roster_index) select new.id,p,position from jsonb_array_elements_text(new.state->'roster') with ordinality as players(p,position);
  else update wordpairs.matches set status=new.state->>'status' where id=new.id;
  end if;
  for r in select value from jsonb_array_elements(new.state->'rounds') loop
    if not exists(select 1 from wordpairs.rounds where id=r->>'id') then
      insert into wordpairs.rounds(id,match_id,pair_id,pair_version,round_index,stage,started_at,stage_due_at,revealed,ended_at)
        values(r->>'id',new.id,r->>'pairId',(r->>'pairVersion')::integer,(select ordinality from jsonb_array_elements(new.state->'rounds') with ordinality where value->>'id'=r->>'id'),(r->>'stage')::integer,to_timestamp((r->>'startedAt')::double precision/1000),to_timestamp((r->>'stageDueAt')::double precision/1000),(r->>'revealed')::boolean,to_timestamp((r->>'endedAt')::double precision/1000));
    else
      update wordpairs.rounds set stage=(r->>'stage')::integer,stage_due_at=to_timestamp((r->>'stageDueAt')::double precision/1000),revealed=(r->>'revealed')::boolean,ended_at=to_timestamp((r->>'endedAt')::double precision/1000) where id=r->>'id' and match_id=new.id;
    end if;
    for a in select value from jsonb_array_elements(coalesce(r->'attempts','[]')) loop
      select value into s from jsonb_array_elements(r->'solves') where value->>'profileId'=a->>'profileId' and value->>'stage'=a->>'stage';
      insert into wordpairs.submissions(round_id,profile_id,stage,correct,accepted_at,points,elapsed_ms)
        values(r->>'id',a->>'profileId',(a->>'stage')::integer,(a->>'correct')::boolean,to_timestamp((a->>'acceptedAt')::double precision/1000),coalesce((s->>'points')::integer,0),greatest(0,coalesce((s->>'elapsedMs')::integer,((a->>'acceptedAt')::bigint-(r->>'startedAt')::bigint)::integer))) on conflict do nothing;
    end loop;
  end loop;
  return new;
end $$;
create trigger sync_match_projection after insert or update on wordpairs.aggregates for each row execute function wordpairs.sync_match_projection();

create function wordpairs.award_match_profiles() returns trigger language plpgsql set search_path=pg_catalog,wordpairs as $$
declare award record; profile_version integer; finish_ms bigint; room_state jsonb; room_version integer; begin
  if new.kind<>'match' or new.state->>'status'<>'finished' or old.state->>'status'='finished' then return new; end if;
  finish_ms:=(new.state->>'finishedAt')::bigint;
  if jsonb_typeof(new.state->'finalAwards') is distinct from 'array' or jsonb_array_length(new.state->'finalAwards') is distinct from jsonb_array_length(new.state->'roster') or
    (select count(distinct value->>'profileId') from jsonb_array_elements(new.state->'finalAwards'))<>jsonb_array_length(new.state->'roster') or
    exists(select 1 from jsonb_array_elements(new.state->'finalAwards') a where not (new.state->'roster' ? (a->>'profileId')) or (a->>'points')::integer not between 0 and 40 or jsonb_typeof(a->'winner') is distinct from 'boolean') then raise exception 'Invalid final award scope' using errcode='23514'; end if;
  for award in
    select a->>'profileId' as profile_id,(a->>'points')::integer as points,(a->>'winner')::boolean as winner
      from jsonb_array_elements(new.state->'finalAwards') a order by a->>'profileId' collate "C"
  loop
    insert into wordpairs.profile_match_awards values(new.id,award.profile_id,award.points,award.winner,to_timestamp(finish_ms::double precision/1000)) on conflict do nothing;
    if not found then continue; end if;
    select version into profile_version from wordpairs.aggregates where kind='profile' and id=award.profile_id for update;
    if found then
      update wordpairs.aggregates set version=version+1,state=state||jsonb_build_object('version',version+1,'points',(state->>'points')::integer+award.points,'wins',(state->>'wins')::integer+case when award.winner then 1 else 0 end,'earliestWinAt',case when award.winner then least(coalesce((state->>'earliestWinAt')::bigint,finish_ms),finish_ms) else (state->>'earliestWinAt')::bigint end),updated_at=now() where kind='profile' and id=award.profile_id;
      insert into wordpairs.outbox_events values('match:'||new.id||':award:'||award.profile_id,'profile',award.profile_id,profile_version+1,1,'ProfileGameStatsUpdated',jsonb_build_array(award.profile_id),'{}',now(),null);
    else
      -- Baseline/import fixtures may predate profile aggregates.
      update wordpairs.profiles set points=points+award.points,wins=wins+case when award.winner then 1 else 0 end,earliest_win_at=case when award.winner then least(coalesce(earliest_win_at,to_timestamp(finish_ms::double precision/1000)),to_timestamp(finish_ms::double precision/1000)) else earliest_win_at end where id=award.profile_id;
    end if;
  end loop;
  select state,version into room_state,room_version from wordpairs.aggregates where kind='room' and id=new.state->>'roomId' for update;
  if room_state->>'status'='playing' then
    update wordpairs.aggregates set version=room_version+1,state=room_state||jsonb_build_object('version',room_version+1,'status','closed','closedAt',finish_ms),closed_at=to_timestamp(finish_ms::double precision/1000),updated_at=now() where kind='room' and id=new.state->>'roomId';
    insert into wordpairs.outbox_events values('match:'||new.id||':finished','room',new.state->>'roomId',room_version+1,1,'RoomGameFinished',jsonb_build_array()||coalesce((select jsonb_agg(p->>'profileId') from jsonb_array_elements((room_state->'players')||(room_state->'observers')) p),'[]'::jsonb),'{}',now(),null);
  end if;
  return new;
end $$;
create trigger award_match_profiles after update on wordpairs.aggregates for each row execute function wordpairs.award_match_profiles();

create function public.wordpairs_match_claim(p_now bigint,p_limit integer,p_lease text) returns jsonb language plpgsql security definer set search_path=pg_catalog,wordpairs as $$
declare result jsonb; begin
  if p_limit is null or p_limit not between 1 and 25 or p_lease is null or length(p_lease) not between 1 and 128 then raise exception 'Invalid claim' using errcode='22023'; end if;
  update wordpairs.deadline_jobs j set completed_at=to_timestamp(p_now::double precision/1000) from wordpairs.aggregates a where j.aggregate_kind='match' and j.kind='stage' and j.completed_at is null and a.kind='match' and a.id=j.aggregate_id and a.version<>j.expected_version;
  with candidates as (select id from wordpairs.deadline_jobs where aggregate_kind='match' and kind='stage' and completed_at is null and due_at<=to_timestamp(p_now::double precision/1000) and (lease_until is null or lease_until<=to_timestamp(p_now::double precision/1000)) order by due_at,id collate "C" limit p_limit for update skip locked),
  claimed as (update wordpairs.deadline_jobs j set lease_id=p_lease,lease_until=to_timestamp((p_now+30000)::double precision/1000) from candidates c where j.id=c.id returning j.*)
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'aggregateId',aggregate_id,'expectedVersion',expected_version,'kind',kind,'dueAt',floor(extract(epoch from due_at)*1000)::bigint) order by due_at,id collate "C"),'[]') into result from claimed;
  return result;
end $$;
create function public.wordpairs_match_complete(p_id text,p_lease text) returns boolean language plpgsql security definer set search_path=pg_catalog,wordpairs as $$
begin update wordpairs.deadline_jobs set completed_at=now(),lease_until=null where id=p_id and lease_id=p_lease and aggregate_kind='match' and kind='stage';return found;end $$;
revoke all on function wordpairs.freeze_category(),wordpairs.sync_match_projection(),wordpairs.award_match_profiles() from public,anon,authenticated;
do $$ declare fn regprocedure; begin
  for fn in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname like 'wordpairs_match_%' or p.proname='wordpairs_catalog') loop
    execute format('revoke all on function %s from public,anon,authenticated',fn);execute format('grant execute on function %s to service_role',fn);
  end loop;
end $$;
commit;

